-- Migration: Retailer Portal Credit Card Management & Audit Logs
-- Conventions: ref_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
-- concise columns, strict multi-tenant & retailer scoping, PCI-safe masked/hashed storage.

CREATE TABLE IF NOT EXISTS public.retailer_credit_cards (
    ref_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE,
    tenant_id UUID NULL,
    company_ref_id BIGINT NOT NULL,
    retailer_ref_id BIGINT NOT NULL,
    user_type_ref_id BIGINT NOT NULL DEFAULT 2,
    user_ref_id BIGINT NULL,
    card_name VARCHAR(150) NOT NULL,
    mobile_no VARCHAR(15) NOT NULL,
    card_fingerprint VARCHAR(64) NOT NULL,
    masked_card_no VARCHAR(32) NOT NULL,
    card_last4 VARCHAR(4) NOT NULL,
    card_bin6 VARCHAR(6) NULL,
    card_type_ref_id BIGINT NULL,
    card_type VARCHAR(100) NOT NULL DEFAULT 'Credit Card',
    bank_id INTEGER NULL,
    bank_name VARCHAR(200) NOT NULL,
    bank_short_code VARCHAR(50) NULL,
    bill_gen_day INTEGER NOT NULL,
    bill_due_day INTEGER NOT NULL,
    last_paid_cycle VARCHAR(10) NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_retailer_credit_cards_scope_fingerprint
        UNIQUE (company_ref_id, retailer_ref_id, card_fingerprint)
);

CREATE INDEX IF NOT EXISTS ix_retailer_credit_cards_scope
    ON public.retailer_credit_cards (company_ref_id, retailer_ref_id, is_deleted);

CREATE INDEX IF NOT EXISTS ix_retailer_credit_cards_fingerprint
    ON public.retailer_credit_cards (card_fingerprint);

CREATE TABLE IF NOT EXISTS public.retailer_card_audit_logs (
    ref_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    card_ref_id BIGINT NULL REFERENCES public.retailer_credit_cards(ref_id) ON DELETE SET NULL,
    tenant_id UUID NULL,
    company_ref_id BIGINT NOT NULL,
    retailer_ref_id BIGINT NOT NULL,
    user_type_ref_id BIGINT NOT NULL DEFAULT 2,
    user_ref_id BIGINT NULL,
    action VARCHAR(30) NOT NULL,
    masked_card_no VARCHAR(32) NULL,
    details_json TEXT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS ix_retailer_card_audit_scope
    ON public.retailer_card_audit_logs (company_ref_id, retailer_ref_id, created_at);
